    "commentary": {
      "type": "string",
      "description": "One paragraph, at most six sentences, naming measures and never their values."
    }
  }
};

const f = $('Fetch the figures').first().json;
const doc = {
  trace_id: `weekly-${f.week}`,
  doc_id: null,
  data: JSON.stringify({
